const { getState } = options;
const { grid } = getState();
const selectedRows = grid.selectedRows;
const checksAvailable = window.isSpecialItemType && window.isWorkflowTool && window.isFunctionDisabled;
if (selectedRows.length === 0 || !checksAvailable) {
	return { hidden: true };
}

const isSpecialItemType = window.isSpecialItemType();
const isWorkflowTool = window.isWorkflowTool();
const isFunctionDisabled = window.isFunctionDisabled(window['RelType_Nm'], 'Copy');
const hidden = isSpecialItemType || isWorkflowTool || isFunctionDisabled;
return { hidden };
